/// Sequences for the older payloads the suite installs (synthetic 4.1.1; shipped 4.1.2-4.1.5).
pub fn sequence_of(version: &str) -> u64 {
    match version {
        "4.1.1" => 11,
        "4.1.2" => 12,
        "4.1.3" => 13,
        "4.1.4" => 14,
        "4.1.5" => 15,
        _ => CURRENT_SEQUENCE,
    }
}
